  if(language==='en' && optimizer)optimizer=prepareEnglishInterpretation(optimizer,'',undefined,{allowMissingTask:true}).value
  const consult = normalizeConsultation(optimizer?.consult)
  if (!optimizer || (!consult && !['clarify', 'add', 'ask'].some(k => optimizer[k]?.length))) return ''
  const en = language === 'en'
  const lines = [en ? '[Prompt assistance: machine interpretation and advice; the original user text remains authoritative.]'
    : '【提示词辅助 · 机器解释与建议，以完整用户原话为准】']
  if (optimizer.intent?.text) lines.push((en ? 'Current intent: ' : '本轮理解：') + optimizer.intent.text)
  if (consult) lines.push((en ? 'Focused consultation opportunity (advice): ' : '具体咨询机会（建议）：')
    + 'consult_task ' + JSON.stringify({ mode: consult.mode, scope: 'general', focus: consult.focus, question: consult.reason })
    + (en ? '\nUse if it can add a missing method or quality gain; use actual result material for improve_result. No automatic call or fixed quota.' : '\n仅在能补上未解决方法或质量增益时使用；improve_result需附实际产物。不是自动调用或固定配额。'))
  const titles = en ? { clarify: 'Clarification', add: 'Positive additions and suggestions', ask: 'Questions to consider' }
    : { clarify: '表达澄清', add: '正向补充与建议', ask: '需要反问的点' }
  for (const key of ['clarify', 'add', 'ask']) if (optimizer[key]?.length) lines.push(titles[key] + '\n' + optimizer[key].map(s => '- ' + s).join('\n'))
  return lines.join('\n\n')
}

